const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const rasheedCoast = ee.Geometry.Polygon([
    [30.35, 31.45],
    [30.35, 31.35], 
    [30.50, 31.35],
    [30.50, 31.45]
  ]);

  const date1984 = {start: '1984-07-25', end: '1984-08-25'};
  const date2021 = {start: '2021-08-01', end: '2021-09-01'};

  // 2. Data Acquisition - Landsat 5 for 1984, Landsat 8 for 2021
  let landsat5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
    .filterBounds(rasheedCoast)
    .filterDate(date1984.start, date1984.end)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  let landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
    .filterBounds(rasheedCoast)
    .filterDate(date2021.start, date2021.end)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  // Check collection sizes
  const size1984 = landsat5.size().getInfo();
  const size2021 = landsat8.size().getInfo();

  console.log(`1984 Images: ${size1984}, 2021 Images: ${size2021}`);

  if (size1984 === 0 || size2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get median composites and calculate NDWI
  const composite1984 = landsat5.median();
  const composite2021 = landsat8.median();

  // NDWI calculation: (Green - NIR) / (Green + NIR)
  const ndwi1984 = composite1984.normalizedDifference(['B2', 'B4']).rename('NDWI');
  const ndwi2021 = composite2021.normalizedDifference(['B3', 'B5']).rename('NDWI');

  // 4. Calculate water area statistics
  const water1984 = ndwi1984.gt(0);
  const water2021 = ndwi2021.gt(0);

  const stats1984 = water1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: rasheedCoast,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = water2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: rasheedCoast,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1984 = stats1984.NDWI || 0;
  const waterPixels2021 = stats2021.NDWI || 0;

  console.log(`Water pixels 1984: ${waterPixels1984}`);
  console.log(`Water pixels 2021: ${waterPixels2021}`);

  // Check for valid pixels
  if (waterPixels1984 === 0 || waterPixels2021 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Analysis - Compare water areas to detect shoreline change
  // If water area decreased, shoreline retreated inland
  const waterChange = waterPixels2021 - waterPixels1984;
  console.log(`Water change: ${waterChange.toFixed(0)} pixels`);

  // Validate result
  if (waterChange === null || Math.abs(waterChange) > 100000) {
    console.log("<answer>C3</answer>");
    return;
  }

  // If water area decreased (negative change), shoreline retreated inland
  if (waterChange < -100) { // Threshold to account for noise
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
